from .base_verifier import BaseVerifier


class RateLimiter(BaseVerifier):
    def __init__(self, max_requests: int, time_window: int):
        self.max_requests = max_requests
        self.time_window = time_window
        self.requests = {}

    def verify(self, transaction) -> bool:
        import time
        current_time = time.time()
        transaction_id = transaction.transaction_id

        if transaction_id not in self.requests:
            self.requests[transaction_id] = []

        self.requests[transaction_id] = [
            t for t in self.requests[transaction_id]
            if current_time - t < self.time_window
        ]

        if len(self.requests[transaction_id]) >= self.max_requests:
            return False

        self.requests[transaction_id].append(current_time)
        return True
